import{_ as t,o,c as a,a2 as s}from"./chunks/framework.CPZ999nZ.js";const u=JSON.parse('{"title":"Panoramic cases","description":"","frontmatter":{},"headers":[],"relativePath":"development/panoramic.md","filePath":"development/panoramic.md","lastUpdated":1795522506000}'),d={name:"development/panoramic.md"};function i(n,e,c,r,h,l){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="panoramic-cases" tabindex="-1">Panoramic cases <a class="header-anchor" href="#panoramic-cases" aria-label="Permalink to &quot;Panoramic cases&quot;">​</a></h1><p>Panoramic is the test runner for the integration and correctness suites. This page is for people who write or run cases. <a href="./testing">Testing</a> says what each kind of test is for.</p><p>A case is a directory with a <code>config.yaml</code> and the files it uses. Panoramic runs the participants the case names, runs the steps of its procedure against them, and reports what happened. The same file runs on each OS it declares.</p><h2 id="the-two-suites" tabindex="-1">The two suites <a class="header-anchor" href="#the-two-suites" aria-label="Permalink to &quot;The two suites&quot;">​</a></h2><p>The cases live in two directories, one for each purpose. Panoramic runs both the same way, and any step can appear in either. The directory says what a case is for.</p><ul><li><strong><code>test/integration/cases</code></strong> checks ADP on its own. A case starts ADP, usually with the Agent, and checks that it starts, stays up, logs what it should, listens on its endpoints, exits as expected, and sends the expected metrics to a mock intake. Each case runs on every OS in its <code>subject_os</code>: Linux, macOS, Windows, or more than one. See <a href="#writing-an-integration-case">Writing an integration case</a>.</li><li><strong><code>test/correctness/cases</code></strong> compares ADP with the Datadog Agent. A case sends the same load to both, gives each its own mock intake, and ends with a <code>compare</code> step. The cases run on Linux. See <a href="#writing-a-comparison-case">Writing a comparison case</a>.</li></ul><h2 id="what-a-case-is" tabindex="-1">What a case is <a class="header-anchor" href="#what-a-case-is" aria-label="Permalink to &quot;What a case is&quot;">​</a></h2><ul><li><strong>The name.</strong> The directory names the case. The name must be unique among the cases of one run. Panoramic loads only the direct subdirectories of a <code>-d</code> directory that hold a <code>config.yaml</code>.</li><li><strong>The suite.</strong> The directory above <code>cases/</code> names the suite. <code>test/integration/cases/adp-cmd-host</code> is in the <code>integration</code> suite, and <code>test/correctness/cases/dsd-plain</code> is in <code>correctness</code>. The suite names the case&#39;s log directory.</li><li><strong>The subject.</strong> One participant sets <code>subject: true</code>. It is the software under test.</li><li><strong>Participants.</strong> A participant is one piece of software: an image, a pod, or programs on the host. A case names each one. A participant name is a lowercase DNS label, because it becomes a container name and a host name. <code>self</code>, <code>localhost</code>, names of only digits and <code>0x</code> numbers are errors. The names of endpoints, processes, commands and connections start with a lowercase letter and hold lowercase letters, digits and <code>_</code>.</li><li><strong>Participant types.</strong> <code>type:</code> names a piece of software that panoramic knows: <code>agent-adp</code>, <code>agent</code>, <code>datadog-intake</code> or <code>millstone</code>. The type fills in the image, the command, the environment, the endpoints and the checks of the software. A participant with no type writes all of that itself.</li><li><strong>Realization.</strong> A realization is how a participant runs: a Linux container, a Windows container, a pod, or host processes. The subject runs in the default of the subject OS: a Linux container on Linux, host processes on macOS, and a Windows container on Windows. Every other participant follows the subject. A case sets <code>realization</code> only when the realization is under test.</li><li><strong><code>subject_os</code>.</strong> The list of OSes the case runs on: <code>linux</code>, <code>macos</code> or <code>windows</code>. A run selects one. A case that does not list it is skipped, with the reason.</li></ul><p>The working examples are in <code>bin/correctness/panoramic/testdata/examples/</code>. The cases under <code>bin/correctness/panoramic/testdata/bad/</code> show the errors that panoramic finds before it starts anything. Each one has the substring of its error in <code>expected.yaml</code>.</p><h2 id="running-cases" tabindex="-1">Running cases <a class="header-anchor" href="#running-cases" aria-label="Permalink to &quot;Running cases&quot;">​</a></h2><p>Use the Make targets. They build what a run needs.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test-integration</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # build the images, run every integration case</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test-integration-quick</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # run every integration case, with the images that exist</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list-integration-tests</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # list the integration cases</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test-correctness</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # run every correctness case</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test-correctness-case</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CASE=dsd-plain</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test-integration-macos-ci</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # on macOS: run the cases that declare macOS</span></span></code></pre></div><p><code>panoramic</code> takes the same options when you run it yourself. Build it with <code>make build-panoramic</code> and the courier with <code>make build-courier</code>. The courier is the program panoramic runs inside containers and pods.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/release/panoramic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test/integration/cases</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> adp-cmd-host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-tui</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/release/panoramic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test/integration/cases</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --subject-os</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/release/panoramic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test/integration/cases/adp-cmd-host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --subject-os</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Option</th><th>Meaning</th></tr></thead><tbody><tr><td><code>-d &lt;dir&gt;</code></td><td>A directory of cases. Repeat it for more than one.</td></tr><tr><td><code>-t &lt;names&gt;</code></td><td>Run only these cases, as a comma-separated list. A name that matches nothing is an error.</td></tr><tr><td><code>--subject-os &lt;os&gt;</code></td><td>The OS to run for. It defaults to the OS of the host.</td></tr><tr><td><code>--set &lt;name&gt;=&lt;reference&gt;</code></td><td>Run <code>&lt;reference&gt;</code> where a case names the image or host program <code>&lt;name&gt;</code>.</td></tr><tr><td><code>-p &lt;n&gt;</code></td><td>How many cases run at once. The default is 4.</td></tr><tr><td><code>-f</code>, <code>--fail-fast</code></td><td>Stop after the first failure.</td></tr><tr><td><code>--no-tui</code></td><td>Print plain text, not the terminal display.</td></tr><tr><td><code>-o json</code></td><td>Print the run report as JSON.</td></tr><tr><td><code>-l &lt;dir&gt;</code>, <code>PANORAMIC_LOG_DIR</code></td><td>The base directory for logs. The default is the temporary directory. Each run makes a timestamped subdirectory.</td></tr><tr><td><code>-v</code></td><td>Print the details of every step.</td></tr><tr><td><code>--log-level &lt;level&gt;</code></td><td>The log level of panoramic and its libraries. The default is <code>info</code>.</td></tr><tr><td><code>--kind-cluster-name &lt;name&gt;</code>, <code>--no-delete-kind-cluster</code></td><td>The kind cluster of the cases that run pods, and whether to keep it after the run.</td></tr></tbody></table><p><code>PANORAMIC_SET</code> takes the <code>--set</code> entries as a comma-separated list. CI uses it to run the cases against the images a pipeline built. <code>NAME</code> is the reference exactly as the case or the participant type writes it. A name given twice is an error. A name that no case uses is an error too.</p><p>On macOS, <code>--set</code> also runs the host-process cases against other builds or installs of ADP and the Agent. This example uses a debug build of ADP and the system-wide Agent in <code>/opt/datadog-agent</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/release/panoramic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test/integration/cases</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-tui</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/release/agent-data-plane=target/debug/agent-data-plane</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/saluki-dda/datadog-agent/bin/agent/agent=/opt/datadog-agent/bin/agent/agent</span></span></code></pre></div><p><code>make test-integration-macos-run</code> sets the two names itself. To give it another Agent, set <code>MACOS_TEST_AGENT_INSTALL_DIR</code>.</p><p><code>panoramic list</code> leaves out a case that does not declare the subject OS. With <code>--json</code> it prints one entry for each case with its <code>suite</code>, its <code>runtime</code> and its <code>timeout</code>. The <code>runtime</code> is <code>linux</code>, <code>mac</code> or <code>windows</code>, or <code>kubernetes_in_docker</code> for a case that runs pods. The CI generator reads it.</p><p><code>panoramic plan &lt;case&gt; --subject-os &lt;os&gt;</code> prints what the case does on that OS as JSON, and starts nothing. <code>--text</code> prints the same for people. It shows each participant&#39;s realization, image, command, environment and files, each endpoint and connection with its address, and the order in which participants start. It plans the case for every OS in <code>subject_os</code>, so a field that fails on any of them is an error on any host.</p><h3 id="checks-before-the-first-case" tabindex="-1">Checks before the first case <a class="header-anchor" href="#checks-before-the-first-case" aria-label="Permalink to &quot;Checks before the first case&quot;">​</a></h3><p>Before any case starts, one check covers the whole selection. It runs outside the timeout of every case.</p><ol><li>Each realization that the cases need is available: a Docker daemon for containers, <code>kind</code> for pods, and the right host OS for host processes. A Windows container needs a Windows host. Host processes need macOS or Linux.</li><li>Each image is in the daemon. Panoramic pulls an image that is missing, once.</li><li>Each host program exists and runs. <code>./x</code> is a file of the participant, so it is found later. A bare name is found on the <code>PATH</code>. Any other path is relative to the directory panoramic runs in.</li><li>The courier exists for each container OS in use.</li><li>For pods, the kind cluster exists and holds the images. Panoramic makes a missing cluster. The cluster must have one node.</li></ol><p>A failed check is a harness error that names the case. The run stops with exit code 2 before any case starts.</p><h3 id="which-cases-run-at-once" tabindex="-1">Which cases run at once <a class="header-anchor" href="#which-cases-run-at-once" aria-label="Permalink to &quot;Which cases run at once&quot;">​</a></h3><p>Cases in containers and pods run in parallel, up to <code>-p</code>. Cases with host processes run one at a time, because their ports are fixed.</p><h3 id="ci" tabindex="-1">CI <a class="header-anchor" href="#ci" aria-label="Permalink to &quot;CI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Job</th><th>What it runs</th></tr></thead><tbody><tr><td><code>test-integration</code></td><td>Every integration case on Linux, with the images the pipeline built.</td></tr><tr><td><code>test-integration-macos-arm64</code>, <code>test-integration-macos-amd64</code></td><td>The cases that declare macOS, as host processes.</td></tr><tr><td><code>test-integration-windows-amd64</code></td><td>The cases that declare Windows, in Windows containers.</td></tr><tr><td><code>generate-correctness-pipeline</code></td><td>Makes one <code>test-correctness-&lt;case&gt;</code> job for each correctness case.</td></tr><tr><td><code>run-correctness-tests</code></td><td>Runs the generated jobs. A case with pods gets the longer kind template.</td></tr></tbody></table><h2 id="the-case-file" tabindex="-1">The case file <a class="header-anchor" href="#the-case-file" aria-label="Permalink to &quot;The case file&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;text&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # optional</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">timeout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;duration&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # required, with a unit: 20m, 180s</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">disabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                         # optional: the case is checked, and no run includes it</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">subject_os</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">linux</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">macos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">windows</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># required, at least one</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">participants</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  &lt;name&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;participant&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # exactly one has subject: true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">procedure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;step&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">parallel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;step&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]            </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># assertions only, no nesting</span></span></code></pre></div><p>A key that its owner does not know is an error before anything starts. The cases under <code>testdata/bad/</code> pin such errors.</p><h3 id="a-participant" tabindex="-1">A participant <a class="header-anchor" href="#a-participant" aria-label="Permalink to &quot;A participant&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>type</code></td><td>A participant type. Without it, the case writes the participant in full.</td></tr><tr><td><code>subject</code></td><td><code>true</code> for the software under test.</td></tr><tr><td><code>realization</code></td><td><code>{enclosure, options}</code>. The enclosures are <code>linux-container</code>, <code>windows-container</code>, <code>kubernetes-pod</code> and <code>host-process-group</code>.</td></tr><tr><td><code>connect</code></td><td><code>{&lt;name&gt;: &lt;participant&gt;.&lt;endpoint&gt;}</code>: the endpoints this participant uses.</td></tr><tr><td><code>with</code></td><td>Parameters of the participant type. It is an error without <code>type</code>.</td></tr><tr><td><code>image</code>, <code>command</code>, <code>args</code></td><td>What runs in a container or pod. <code>command</code> replaces the entrypoint of the image, and <code>args</code> replaces its arguments.</td></tr><tr><td><code>programs</code></td><td>A list of <code>{name, path, args, env}</code>. What runs as host processes.</td></tr><tr><td><code>env</code></td><td><code>{NAME: &quot;text&quot;}</code>. The environment of every process. Quote each value.</td></tr><tr><td><code>files</code></td><td><code>{&lt;destination or name&gt;: &lt;source&gt;}</code>. Files placed before the participant starts.</td></tr><tr><td><code>endpoints</code></td><td><code>{&lt;name&gt;: {protocol, port | path | name}}</code>. Where the participant listens.</td></tr><tr><td><code>ready</code></td><td><code>{&lt;endpoint&gt;: &lt;evidence&gt;}</code>. How panoramic knows an endpoint is ready.</td></tr><tr><td><code>processes</code></td><td>A list of <code>{name, exit, output}</code>: the processes that steps name, and how each is observed. See <a href="#observation">Observation</a>.</td></tr><tr><td><code>commands</code></td><td><code>{&lt;name&gt;: [&lt;program&gt;, &lt;arg&gt;, ...]}</code>, or <code>{program, argv, env}</code>. Command lines that <code>exec</code> and the operations run by name. <code>program</code> names a program of host processes.</td></tr><tr><td><code>mounts</code></td><td>A list of <code>{host, path, read_only}</code>. Host paths in a Linux container or pod.</td></tr><tr><td><code>collect</code></td><td>A list of <code>{path, name, keep}</code>. Files copied out after the procedure. <code>keep</code> is <code>always</code> or <code>on_failure</code>.</td></tr></tbody></table><p>The case&#39;s fields lie over the fields of the participant type. A map merges by key, and an entry of the case replaces the entry of the type with the same key. Every other field replaces the field below it. A case that sets <code>command</code> and not <code>args</code> drops the <code>args</code> of the type. The type&#39;s own checks run on the result.</p><p>A case that sets <code>image</code> on host processes, or <code>programs</code> in a container, is an error. Two more guards stop a change that would fail without a message:</p><ul><li>A case that sets <code>command</code> or <code>args</code>, or replaces a file that a participant type uses to supervise its processes, must set <code>processes</code> too. Without it, no exit record is written, and a process that never started reads as running.</li><li>A case that makes a connection must not set the environment variable that the connection delivers. The case&#39;s value would win over the delivered one.</li></ul><p><code>realization.options</code> are booleans. A Linux container takes <code>host_pid</code> and <code>host_cgroup_namespace</code>. A pod takes <code>host_pid</code> and <code>cri_socket</code>.</p><h3 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h3><p>A key that looks like a path is a destination. Any other key must be a name that the participant type declares, such as <code>datadog.yaml</code>. A name belongs to some realizations only. <code>agent-adp</code> and <code>agent</code> declare <code>datadog.yaml</code>, and <code>agent</code> declares <code>otel-config.yaml</code>, in a Linux container or pod. On macOS and Windows, write a destination: <code>./datadog.yaml</code> for macOS host processes, and <code>C:/ProgramData/Datadog/datadog.yaml</code> for a Windows container. Planning checks every OS in <code>subject_os</code>, so a name that one of them does not declare is an error even when the case runs on another.</p><table tabindex="0"><thead><tr><th>Realization</th><th>A destination is</th></tr></thead><tbody><tr><td>Linux container, pod</td><td>An absolute path.</td></tr><tr><td>Windows container</td><td>A path on drive <code>C:</code>, written with <code>/</code> or <code>\\</code>.</td></tr><tr><td>Host process</td><td><code>./…</code>, under the directory of the participant, with no <code>..</code>.</td></tr></tbody></table><p>A destination that ends in a separator is a directory. The value is a source path, relative to the case directory, or <code>{from, template, mode}</code>. A source stays inside the suite directory. <code>template: true</code> marks a UTF-8 file whose references panoramic fills in. Every other file is copied byte for byte. <code>mode</code> is a quoted octal string such as <code>&quot;0755&quot;</code>, and the default is <code>&quot;0644&quot;</code>. <code>mode</code> is an error on a Windows participant. Two entries that land on one path are an error, and so is a path that panoramic reserves.</p><h3 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h3><div><p>A reference is a value that panoramic owns, written between double braces. It has one of these forms:</p><ul><li><code>{{ self.endpoints.api.port }}</code>: the <code>port</code>, <code>path</code> or <code>name</code> of an endpoint. <code>self</code> is the participant that holds the text. In a step, a participant name replaces <code>self</code> to name another participant&#39;s endpoint. A participant cannot do that: it declares <code>connect</code> and reads the endpoint through <code>self.connections</code>.</li><li><code>{{ self.connections.intake.url }}</code>: the <code>url</code>, <code>host</code>, <code>port</code> or <code>path</code> of an endpoint that this participant connects to.</li><li><code>{{ self.dir }}</code>: the directory of the participant. <code>ip</code>, <code>container_id</code> and <code>pod_uid</code> read the same way.</li></ul><p>A reference is valid in <code>command</code>, <code>args</code>, <code>env</code>, the programs&#39; arguments and environment, a template file, a readiness pattern and the arguments of a named command. A step takes one only in its template fields. Each <code>{{</code> starts a reference, and there is no escape. Panoramic checks that every reference names something that exists and that its value is known in time.</p><h3 id="endpoints-and-connections" tabindex="-1">Endpoints and connections <a class="header-anchor" href="#endpoints-and-connections" aria-label="Permalink to &quot;Endpoints and connections&quot;">​</a></h3><p>An endpoint has a protocol and one address field.</p><table tabindex="0"><thead><tr><th>Protocol</th><th>Address</th></tr></thead><tbody><tr><td><code>tcp</code>, <code>udp</code>, <code>http</code>, <code>grpc</code></td><td><code>port</code>. <code>http</code> takes <code>tls: true</code>.</td></tr><tr><td><code>unix_datagram</code>, <code>unix_stream</code></td><td><code>path</code></td></tr><tr><td><code>named_pipe</code></td><td><code>name</code> (Windows only)</td></tr></tbody></table><p>The harness owns each address. A case does not pick a free port: it writes the reference, and panoramic fills in the value. A participant type already wires its own listeners through its default environment.</p><p><code>connect: {name: other.endpoint}</code> makes the endpoint of another participant known to this one. A participant type names the connections it understands, and each one sets environment for the software. <code>agent-adp</code> and <code>agent</code> take <code>intake</code> and <code>dogstatsd_forward</code>. <code>millstone</code> takes <code>comparison_target</code> and <code>baseline_target</code>. A participant with no type reads its connections through <code>{{ self.connections.&lt;name&gt;.url }}</code>. A connection that nothing uses is an error.</p><p><code>ready</code> says when an endpoint is ready: <code>accepts</code>, <code>exists</code>, <code>none</code>, <code>{http: &lt;path&gt;}</code> or <code>{output: &lt;pattern&gt;, process: &lt;name&gt;}</code>. A participant that listens on an endpoint starts before the participants that connect to it.</p></div><h3 id="errors-that-panoramic-finds-first" tabindex="-1">Errors that panoramic finds first <a class="header-anchor" href="#errors-that-panoramic-finds-first" aria-label="Permalink to &quot;Errors that panoramic finds first&quot;">​</a></h3><p><code>list</code>, <code>plan</code> and <code>run</code> load every case and plan it for every OS in <code>subject_os</code>. The errors include:</p><ul><li>an unknown key, more or less than one subject, or a participant type that does not support the realization;</li><li>a file source that is missing, or outside the suite directory;</li><li>two files on one path, or a destination that does not fit the realization;</li><li>two endpoints with one address, or a <code>connect</code> target that does not exist;</li><li>a reference to something that does not exist, or whose value is not known in time;</li><li>a cycle in the order of creation or start;</li><li>a step that does not decode, or that names a participant, process, command, operation or endpoint that does not exist on that OS.</li></ul><p>Panoramic cannot check that a program exists in an image, that a script is correct, or that the software opens its listeners. Those fail at start, in <code>exec</code>, or at a readiness timeout, with the output attached.</p><h2 id="participant-types" tabindex="-1">Participant types <a class="header-anchor" href="#participant-types" aria-label="Permalink to &quot;Participant types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Software</th><th>Realizations</th></tr></thead><tbody><tr><td><code>agent-adp</code></td><td>The Datadog Agent with ADP.</td><td>Linux container, pod, macOS host processes, Windows container</td></tr><tr><td><code>agent</code></td><td>The Datadog Agent alone, as the baseline of a comparison.</td><td>Linux container, pod</td></tr><tr><td><code>datadog-intake</code></td><td>The mock intake. It records what it receives.</td><td>Linux container, pod</td></tr><tr><td><code>millstone</code></td><td>The load generator.</td><td>Linux container, pod</td></tr></tbody></table><p><strong><code>agent-adp</code> and <code>agent</code>.</strong> The default image is <code>saluki-images/datadog-agent:testing-devel</code>, and a case writes another image with <code>image:</code>. Both take the default environment from <code>DEFAULT_ENV</code> in <code>bin/correctness/panoramic/src/participants/datadog_agent.rs</code>. That environment moves every listener off its default port. A port that a case binds must be below 49152, because macOS hands out the ports above it to outbound connections.</p><p>A case that sets a key of <code>datadog.yaml</code> hides the default environment entry of the same setting. The default entry is withdrawn, and the case must wire the endpoint itself. Panoramic says so when it does not. The same holds when the case sets <code>ADP_DD_&lt;NAME&gt;</code> for <code>DD_&lt;NAME&gt;</code>, or another name that the software reads for the setting.</p><ul><li><em>Endpoints of <code>agent-adp</code>.</em> <code>dogstatsd_udp</code>, <code>apm_tcp</code>, <code>api</code>, <code>agent_otlp_grpc</code> and <code>agent_otlp_http</code> exist by default. Opt-in endpoints are <code>otlp_grpc</code>, <code>otlp_http</code>, <code>dogstatsd_tcp</code>, <code>dogstatsd_uds</code>, <code>dogstatsd_uds_stream</code> and <code>apm_uds</code> (Linux only), and <code>dogstatsd_pipe</code> on Windows. The case turns one on when it writes the reference under the key that the software reads.</li><li><em>Endpoints of <code>agent</code>.</em> <code>dogstatsd_udp</code>, <code>apm_tcp</code>, <code>agent_otlp_grpc</code>, <code>agent_otlp_http</code> and <code>otel_otlp_grpc</code> exist by default. <code>otel_otlp_grpc</code> is for the collector in <code>otel-config.yaml</code>, which the case places as a template. <code>dogstatsd_uds</code>, <code>dogstatsd_uds_stream</code> and <code>apm_uds</code> are opt in.</li><li><em><code>with</code>.</em> <code>host_view: true</code> mounts <code>/proc</code> and the cgroup tree of the host, and the Docker socket where there is one, and points the software at them. It is not for host processes or Windows. <code>own_ip: {env: [...], hosts: [...]}</code> sets each variable in <code>env</code> to the address of the participant, and maps each name in <code>hosts</code> to it. It is for <code>agent-adp</code> in a container.</li><li><em>Files.</em> In a Linux container or pod, <code>datadog.yaml</code> is a name that stands for the file the software reads. <code>agent</code> also has <code>otel-config.yaml</code>. Other realizations take a destination. See <a href="#files">Files</a>.</li><li><em>Processes.</em> <code>agent-adp</code> has <code>adp</code> and <code>agent</code>. <code>agent</code> has <code>agent</code>.</li><li><em>Commands.</em> <code>agent-adp</code> names <code>adp</code> and <code>agent</code>.</li><li><em>Operations.</em> <code>agent-adp</code> offers <code>config_dump</code>, <code>config_set</code>, <code>dogstatsd_capture</code>, <code>dogstatsd_replay</code> and <code>dogstatsd_stats</code>.</li><li><em>macOS.</em> ADP and the Agent are two programs. The paths are <code>target/release/agent-data-plane</code> and <code>/tmp/saluki-dda/datadog-agent/bin/agent/agent</code>. <code>--set</code> replaces each. <code>host_view</code> and <code>ADP_DD_</code> keys are errors.</li><li><em>Windows.</em> The image is <code>saluki-images/agent-data-plane:testing-windows</code>. It adds no entrypoint of its own. Panoramic replaces the base image&#39;s entrypoint with one that starts the Agent and then ADP, writes their logs and exit records, and restarts nothing. It keeps the container up after both exit, so panoramic can read what they left.</li></ul><p><strong><code>datadog-intake</code>.</strong> It takes no <code>with</code>. It has the endpoints <code>api</code> (HTTP) and <code>dogstatsd_forward</code> (UDP), and the operation <code>dump</code>. It runs from <code>saluki-images/correctness-tools:latest</code>. Connect an <code>agent-adp</code> or <code>agent</code> participant to its <code>api</code> endpoint as <code>intake</code>.</p><p><strong><code>millstone</code>.</strong> It runs two senders in one container with the same seed, so each sends the same payloads. The case supplies <code>millstone.yaml</code> with <code>template: true</code>, and its target is a field of the <code>comparison_target</code> connection. Panoramic derives the file of the baseline sender from it. The processes are <code>comparison</code> and <code>baseline</code>. In a container, the participant also collects the input capture of the baseline sender.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><p>A step is a map with a <code>step</code> key and the fields of the step. Every field is required unless the table says so. <code>on</code> names a participant. A duration has a unit: <code>500ms</code>, <code>30s</code>, <code>5m</code>. A step has a budget, which is its <code>timeout</code>, <code>duration</code> or <code>during</code>. A step that does not report within its budget and 10 seconds of slack is <code>errored</code>. The case timeout stops a step that is still running, and the step is <code>interrupted</code>. A step takes a reference only in its template fields: <code>pattern</code> of the two log steps, <code>path</code> of <code>file_contains</code>, and <code>command</code>, <code>args</code> and <code>env</code> of <code>exec</code>.</p><table tabindex="0"><thead><tr><th>Step</th><th>Fields</th><th>What it checks or does</th></tr></thead><tbody><tr><td><code>log_contains</code></td><td><code>on</code>, <code>process</code> (optional), <code>pattern</code>, <code>regex</code> (optional), <code>timeout</code></td><td>A line of the process output holds the text. Without <code>process</code>, it searches every process and the container log.</td></tr><tr><td><code>log_not_contains</code></td><td><code>on</code>, <code>pattern</code>, <code>regex</code> (optional), <code>during</code></td><td>Fails as soon as a line holds the text, whether the line is older than the step or arrives during <code>during</code>. Passes after <code>during</code> with no match. It searches every process and the container log.</td></tr><tr><td><code>process_stable_for</code></td><td><code>on</code>, <code>process</code> (optional), <code>duration</code></td><td>The process, or every process, keeps running.</td></tr><tr><td><code>exits_with</code></td><td><code>on</code>, <code>process</code>, <code>code</code>, <code>timeout</code></td><td>The process exits with the code. A death by signal has code 256.</td></tr><tr><td><code>port_listening</code></td><td><code>on</code>, <code>endpoint</code>, <code>timeout</code></td><td>The endpoint accepts a connection.</td></tr><tr><td><code>http_check</code></td><td><code>on</code>, <code>endpoint</code>, <code>path</code>, <code>status</code>, <code>body</code> (optional), <code>insecure_skip_verify</code> (optional), <code>timeout</code></td><td>A <code>GET</code> answers as expected. <code>status</code> is <code>{equal: n}</code> or <code>{not_equal: n}</code>, and <code>body</code> is <code>{equal: text}</code> or <code>{contains: text}</code>. It sends no client certificate, so it cannot reach the privileged routes of ADP.</td></tr><tr><td><code>file_contains</code></td><td><code>on</code>, <code>path</code>, <code>pattern</code>, <code>timeout</code></td><td>A file in the participant holds the text.</td></tr><tr><td><code>config_key_equals</code></td><td><code>on</code>, <code>key</code>, <code>value</code>, <code>view</code>, <code>timeout</code></td><td>A key of the ADP configuration has the value. <code>view</code> is <code>source</code> or <code>runtime</code>.</td></tr><tr><td><code>intake_has_metric</code></td><td><code>on</code>, <code>name</code>, <code>metric_type</code>, <code>value</code>, <code>tags</code>, <code>tags_match</code> (all optional), <code>timeout</code></td><td>An intake holds a metric that meets every criterion.</td></tr><tr><td><code>compare</code></td><td><code>telemetry</code>, <code>comparison</code>, <code>baseline</code>, and options</td><td>The intake participants <code>comparison</code> and <code>baseline</code> hold the same telemetry. <code>telemetry</code> is <code>metrics</code>, <code>traces</code>, <code>logs</code>, <code>events</code> or <code>service_checks</code>. The options are <code>require_dogstatsd_forwarded_packets</code>, <code>otlp_direct_analysis_mode</code> and <code>additional_span_ignore_fields</code> (traces only), and <code>logs</code> (logs only). It has no budget of its own: it has the rest of the case timeout.</td></tr><tr><td><code>exec</code></td><td><code>on</code>, <code>command</code>, <code>args</code> (optional), <code>env</code> (optional), <code>output_contains</code> (optional), <code>timeout</code></td><td>Action. Runs a command in a running participant. <code>command</code> is a list, or the name of a command of the participant.</td></tr><tr><td><code>send</code></td><td><code>on</code>, <code>endpoint</code>, <code>payload</code>, <code>repeat</code> (optional, default 1), <code>timeout</code></td><td>Action. Writes the text of <code>payload</code> to an endpoint <code>repeat</code> times, one datagram or connection each.</td></tr><tr><td><code>config_set</code></td><td><code>on</code>, <code>key</code>, <code>value</code>, <code>timeout</code></td><td>Action. Sets a key of the runtime configuration, with the text <code>value</code>. It retries until <code>timeout</code>.</td></tr><tr><td><code>dogstatsd_replay</code></td><td><code>on</code>, <code>endpoint</code>, <code>payloads</code>, <code>payload_interval</code> (optional), <code>capture_duration</code>, <code>stats_duration</code>, <code>expected_metrics</code>, <code>timeout</code></td><td>Action. Sends payloads while a capture runs, then replays the capture until the statistics hold every expected metric. <code>stats_duration</code> is a whole number of seconds.</td></tr></tbody></table><p>An <code>exec</code> that fails quotes the output of the command. A step needs the participants, processes, endpoints, commands or operations that it names, and the plan checks each for every OS. Three steps need an operation of <code>agent-adp</code>: <code>config_key_equals</code>, <code>config_set</code> and <code>dogstatsd_replay</code>. <code>intake_has_metric</code> and <code>compare</code> need the <code>dump</code> operation of <code>datadog-intake</code>.</p><p><strong><code>intake_has_metric</code>.</strong> Each poll normalizes the metrics in the intake per context and type: a context is the name and the tags, with the host as a <code>host:&lt;value&gt;</code> tag. Counts and rates are summed, sketches are merged, and a gauge takes its latest value, so a value split across flushes is compared as its total. Expect totals: a partial sum can match an early poll. Contexts are never combined, and one context must meet every criterion. <code>value</code> uses approximate float equality, and is an error with <code>metric_type: sketch</code>. <code>tags_match</code> is <code>subset</code>, the default, or <code>exact</code>. Both sides of the tags are sorted and deduplicated first. Under <code>exact</code>, <code>tags: []</code> means no tags and no host. <code>exact</code> does not show that no other context arrived. A failure lists the contexts with the expected name, or the other names when none has it.</p><p>Steps run in order. A step that does not pass stops the procedure, and the steps after it are <code>not_run</code>. A <code>parallel</code> block runs its members together, and holds assertions only. A step reaches a participant through its operations and endpoints, so it does not depend on the participant type.</p><h2 id="observation" tabindex="-1">Observation <a class="header-anchor" href="#observation" aria-label="Permalink to &quot;Observation&quot;">​</a></h2><p>Every process of a participant has one exit channel and one output channel.</p><table tabindex="0"><thead><tr><th>Process</th><th>Exit</th><th>Output</th></tr></thead><tbody><tr><td>A host process</td><td>The wait result of the child</td><td>Its standard output and error</td></tr><tr><td>The only process of a container or pod</td><td>The exit of the container</td><td>The container log</td></tr><tr><td>A supervised process</td><td>A record file that a supervisor appends to</td><td>A log file that panoramic follows</td></tr></tbody></table><p>An exit has three states: running, exited with a status, or undetermined. Undetermined is an observation error. A step that needs the status errors, and no code is invented.</p><p>A supervisor in a container or pod writes an exit record. Panoramic gives every container and pod two environment variables, <code>PANORAMIC_EXIT_DIR</code> and <code>PANORAMIC_LOG_DIR</code>. The format of the record is a contract:</p><ul><li>The record is the file <code>$PANORAMIC_EXIT_DIR/&lt;name&gt;</code>, where <code>&lt;name&gt;</code> is the <code>record</code> of the process.</li><li>The supervisor appends one JSON object for each exit, on its own line: <code>{&quot;code&quot;: 0, &quot;signal&quot;: 0, &quot;time&quot;: &quot;1700000000.25&quot;}</code>.</li><li><code>time</code> is a Unix time in seconds, with one to nine fractional digits.</li><li>A normal exit has <code>signal</code> 0. A death by signal has <code>code</code> 256 and the number of the signal.</li><li>A record with code 256 and no signal, or a signal and another code, is an observation error.</li><li>Other fields are ignored, so the format can grow.</li><li>A line counts once its newline is written.</li><li>The first line is final. A restart never returns a process to running.</li></ul><p>A container reports a death by signal n as code 128 + n. A record and a host program report 256 and the signal. No case asserts on a death by signal.</p><p>A process writes its output under <code>&lt;log dir&gt;/&lt;participant&gt;/&lt;process&gt;.log</code>. A participant with only supervised processes also has its container log, <code>_container.log</code>. A step that names a process searches that process. A <code>log_contains</code> with no process also searches the container log.</p><p>A case declares a supervised process in <code>processes</code>: <code>{name, exit: {record: &lt;file&gt;}, output: {file: &lt;file&gt;}}</code>. Each of <code>exit</code> and <code>output</code> can also be <code>container</code>, for what the realization reports. A <code>&lt;file&gt;</code> is a plain file name. The case must place the supervisor that writes the files.</p><h2 id="host-processes" tabindex="-1">Host processes <a class="header-anchor" href="#host-processes" aria-label="Permalink to &quot;Host processes&quot;">​</a></h2><p>A participant with <code>host-process-group</code> runs its programs on the machine that runs panoramic.</p><ul><li>The state directory is <code>/tmp/panoramic</code>, for every case. Panoramic refuses to start while it exists. The macOS job removes it first.</li><li>One case with host processes runs at a time. The ports are fixed, so two such cases would collide.</li><li>A port that a case binds is below 49152. macOS hands out the ports above it as source ports, and refuses to bind a port that another process holds.</li><li>A program runs with a cleared environment, plus <code>PATH</code>, <code>HOME</code> and <code>TMPDIR</code> of the runner.</li><li>Panoramic stops a program with SIGTERM to its process group, and SIGKILL after two seconds. A descendant that leaves the group, for example with <code>setsid</code>, does not get the signal, and it may outlive the case.</li><li>A process has no record and no output file. A host process on Windows is not built.</li><li>A program that dies by signal n has code 256 and the signal.</li><li>Requests go from the runner to the port of the endpoint, so TLS requests work.</li></ul><h2 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h2><p>Each run makes a directory <code>panoramic-&lt;timestamp&gt;</code> under the log base. The Make targets use <code>target/test-output/panoramic/</code>. Set <code>SALUKI_TEST_OUTPUT_DIR</code> to move the shared root, or <code>PANORAMIC_LOG_DIR</code> to move the base for panoramic alone. <code>make clean-test-logs</code> deletes it.</p><table tabindex="0"><thead><tr><th>File</th><th>Holds</th></tr></thead><tbody><tr><td><code>run.json</code></td><td>The whole run: the state, the totals, the selected cases and their reports.</td></tr><tr><td><code>&lt;suite&gt;/&lt;case&gt;/result.json</code></td><td>One case: its outcome, <code>assertions</code> (one entry for each step), <code>phase_timings</code>, participants, <code>reclaim</code> entries and issues.</td></tr><tr><td><code>&lt;suite&gt;/&lt;case&gt;/result.log</code></td><td>A short text summary of the case.</td></tr><tr><td><code>&lt;suite&gt;/&lt;case&gt;/plan.json</code></td><td>The plan of a case that did not pass, as <code>panoramic plan</code> prints it.</td></tr><tr><td><code>&lt;suite&gt;/&lt;case&gt;/&lt;participant&gt;/</code></td><td>The logs of each process, and <code>collected/</code> with the files the case collects.</td></tr></tbody></table><p><code>run.json</code> changes during the run, so a passing entry does not show that the run finished. Read the state first. Its <code>runtime</code> key names the subject OS as <code>linux</code>, <code>mac</code> or <code>windows</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{state, interrupted_reason, running, not_run}&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.tests[] | select(.outcome != &quot;passed&quot; or (.issues | length) &gt; 0) | &quot;\\(.name) \\(.outcome) \\(.log_dir)&quot;&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run.json</span></span></code></pre></div><p>Treat an unknown state, outcome or status as a failure. Check <code>issues</code> on a pass: they do not change the outcome. The report types are in <code>bin/correctness/panoramic/src/machine_output.rs</code>, and <code>schema_version</code> tells the version. The runner writes <code>plan.json</code> from the settled outcome, so a case that does not pass keeps it, even a case that the run cancelled or dropped after its cleanup grace. A skipped case has no plan. The report lists the file under <code>artifacts</code>.</p><p>The exit code of a run is:</p><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td>0</td><td>Every case passed.</td></tr><tr><td>1</td><td>A step failed.</td></tr><tr><td>2</td><td>A harness error, a case that timed out, or an interrupted run.</td></tr><tr><td>3</td><td>Nothing ran: an empty selection, a name that matches nothing, or every case skipped.</td></tr></tbody></table><p>An <code>errored</code> step could not be evaluated. Read the <code>error</code>, <code>timeout</code>, <code>cause</code> and step <code>message</code> fields first.</p><p><strong>Collected files.</strong> A file that a participant lists in <code>collect</code>, or that a step writes, has <code>keep: always</code> or <code>keep: on_failure</code>. Panoramic applies the rule to the outcome, and <code>result.json</code> lists the files it kept.</p><p><strong>Cleanup.</strong> After every case, panoramic removes what the case made and records each resource as <code>reclaimed</code>, <code>leaked</code> or <code>unsettled</code>, under <code>reclaim</code> in <code>result.json</code>. A container case has one <code>case_scope</code> entry for its containers, network and volume. Host processes have <code>host_process</code> entries, and the state directory has a <code>directory</code> entry. A pod case has a <code>namespace</code> entry and a <code>node_directory</code> entry for its directory on the kind node. A failed removal adds a <code>resource_leaked</code> issue, and an unconfirmed one adds <code>resource_unsettled</code>. Neither changes the outcome.</p><p>Send SIGINT or SIGTERM to stop a run with cleanup. A second signal can leave containers behind.</p><h2 id="writing-an-integration-case" tabindex="-1">Writing an integration case <a class="header-anchor" href="#writing-an-integration-case" aria-label="Permalink to &quot;Writing an integration case&quot;">​</a></h2><p>An integration case runs <code>agent-adp</code> as the subject, and a <code>datadog-intake</code> when it checks what ADP sends. Copy a case from <code>test/integration/cases</code> that uses the same steps.</p><ul><li>When ADP must stay up, end with a <code>parallel</code> block of <code>process_stable_for</code> and a <code>log_not_contains</code> on <code>panic|PANIC</code> with <code>regex: true</code>, so a crash fails the case. When ADP must exit, use <code>exits_with</code>.</li><li>Give each step a budget that covers the start of the Agent and ADP. The cases give a readiness step 30 to 60 seconds, and an <code>intake_has_metric</code> 120 seconds to cover a flush.</li><li>Before a <code>send</code> to a UDP endpoint, wait for the listener&#39;s own startup log with <code>log_contains</code>. A probe cannot confirm a UDP listener, so <code>port_listening</code> is not a readiness gate for it.</li><li>Use <code>config_key_equals</code>, <code>config_set</code> or an <code>exec</code> of the <code>adp</code> command for the privileged API of ADP. <code>http_check</code> cannot reach it.</li><li>List only the OSes in <code>subject_os</code> where the case passes. On macOS and Windows, write a destination for each file. See <a href="#files">Files</a>.</li></ul><h2 id="writing-a-comparison-case" tabindex="-1">Writing a comparison case <a class="header-anchor" href="#writing-a-comparison-case" aria-label="Permalink to &quot;Writing a comparison case&quot;">​</a></h2><p>A comparison case runs the Agent and ADP on the same load and compares what each sends to its own intake. Copy <code>test/correctness/cases/dsd-plain</code>.</p><ul><li>One <code>agent-adp</code> participant is the subject, and one <code>agent</code> participant is the baseline. Both name the image with <code>image:</code>. A run replaces it with <code>--set</code>, and one entry replaces both.</li><li>Each one has its own <code>datadog-intake</code>, and connects to it as <code>intake</code>.</li><li><code>millstone</code> connects <code>comparison_target</code> to the endpoint of ADP, and <code>baseline_target</code> to the endpoint of the Agent. Both senders send the same payloads.</li><li>Wait for the load to finish first. <code>log_contains</code> on <code>load</code>, with <code>process: comparison</code> and then <code>process: baseline</code>, waits for <code>Millstone finished sending</code>.</li><li>Wait for both sides to flush. A sender stays alive once it has sent everything, so the Agent and ADP can still resolve its identity. A <code>process_stable_for</code> on <code>load</code> for a little longer than an aggregation bucket gives them the time to flush.</li><li>End with <code>compare</code>, and name the intake of ADP as <code>comparison</code> and the intake of the Agent as <code>baseline</code>.</li></ul><p>The correctness cases have 8 or 12 minutes to run. A case with pods runs on kind: panoramic creates a missing cluster, with one node.</p>`,92)])])}const g=t(d,[["render",i]]);export{u as __pageData,g as default};
